#!/usr/bin/env node

/**
 * Generate a unified coverage comment with separate sections for:
 * - Worker (Backend) - src/ TypeScript files
 * - Client - client/src/ Preact components
 * - UI (Legacy) - public/js/ Vanilla JS files
 */

const fs = require('fs');
const path = require('path');

// Helper to read JSON safely
function readJSON(filepath) {
  try {
    if (fs.existsSync(filepath)) {
      return JSON.parse(fs.readFileSync(filepath, 'utf8'));
    }
  } catch (e) {
    console.error(`Error reading ${filepath}:`, e.message);
  }
  return null;
}

// Read coverage data
const workerCoverage = readJSON('coverage/coverage-summary.json');
const clientCoverage = readJSON('coverage/client/coverage-summary.json');
const legacyCoverage = readJSON('coverage/legacy/coverage-summary.json');

// Build the comment
let comment = '## 📊 Coverage Report\n\n';

// Worker (Backend) section
if (workerCoverage && workerCoverage.total) {
  const w = workerCoverage.total;
  comment += '### 🔧 Worker (Backend)\n\n';
  comment += '| Metric | Coverage |\n';
  comment += '|--------|----------|\n';
  comment += `| **Lines** | ${w.lines.pct}% |\n`;
  comment += `| **Statements** | ${w.statements.pct}% |\n`;
  comment += `| **Functions** | ${w.functions.pct}% |\n`;
  comment += `| **Branches** | ${w.branches.pct}% |\n\n`;
} else {
  comment += '### 🔧 Worker (Backend)\n\n';
  comment += '_No coverage data available_\n\n';
}

// Client section
if (clientCoverage && clientCoverage.total) {
  const c = clientCoverage.total;
  comment += '### ⚛️ Client (Preact)\n\n';
  comment += '| Metric | Coverage |\n';
  comment += '|--------|----------|\n';
  comment += `| **Lines** | ${c.lines.pct}% |\n`;
  comment += `| **Statements** | ${c.statements.pct}% |\n`;
  comment += `| **Functions** | ${c.functions.pct}% |\n`;
  comment += `| **Branches** | ${c.branches.pct}% |\n\n`;
} else {
  comment += '### ⚛️ Client (Preact)\n\n';
  comment += '_No coverage data available_\n\n';
}

// Legacy UI section
if (legacyCoverage && legacyCoverage.total) {
  const l = legacyCoverage.total;
  const hasData = l.lines.pct !== 'Unknown';
  
  comment += '### 🎨 UI (Legacy)\n\n';
  if (hasData) {
    comment += '| Metric | Coverage |\n';
    comment += '|--------|----------|\n';
    comment += `| **Lines** | ${l.lines.pct}% |\n`;
    comment += `| **Statements** | ${l.statements.pct}% |\n`;
    comment += `| **Functions** | ${l.functions.pct}% |\n`;
    comment += `| **Branches** | ${l.branches.pct}% |\n\n`;
  } else {
    comment += '_No tests for legacy frontend (Vanilla JS files in `public/js/`)_\n\n';
  }
} else {
  comment += '### 🎨 UI (Legacy)\n\n';
  comment += '_No coverage data available_\n\n';
}

comment += '---\n\n';
comment += '_Coverage reports generated by Jest (Worker & Legacy) and Vitest (Client)_\n';

// Write to file
fs.writeFileSync('coverage-comment.md', comment);
console.log('✅ Coverage comment generated successfully');
console.log('\nPreview:\n');
console.log(comment);
